    // Use this to create an icon in code
    public static SVGPath icon(String pathData, Color color, double sizePx) {
        SVGPath p = new SVGPath();
        p.setContent(pathData);
        p.setFill(color);
        double scale = sizePx / 256.0;
        p.setScaleX(scale);
        p.setScaleY(scale);
        return p;
    }
